class Evaluator:
    def __init__(self, expr):
        self.expr = expr
        self.pos = 0
        self.current_char = self.expr[self.pos]

    def error(self):
        raise Exception("Invalid character")

    def advance(self):
        self.pos += 1
        if self.pos < len(self.expr):
            self.current_char = self.expr[self.pos]
        else:
            self.current_char = None

    def skip_whitespace(self):
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def parse_number(self):
        num_str = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            num_str += self.current_char
            self.advance()
        return float(num_str)

    def parse_parentheses(self):
        self.advance()  # skip '('
        result = self.expr_eval()
        self.advance()  # skip ')'
        return result

    def factor(self):
        if self.current_char.isdigit() or self.current_char == '.':
            return self.parse_number()
        elif self.current_char == '(':
            return self.parse_parentheses()
        self.error()

    def term(self):
        result = self.factor()
        while self.current_char is not None and (self.current_char == '*' or self.current_char == '/'):
            op = self.current_char
            self.advance()
            if op == '*':
                result *= self.factor()
            elif op == '/':
                result /= self.factor()
        return result

    def expr_eval(self):
        result = self.term()
        while self.current_char is not None and (self.current_char == '+' or self.current_char == '-'):
            op = self.current_char
            self.advance()
            if op == '+':
                result += self.term()
            elif op == '-':
                result -= self.term()
        return result

def evaluate(expr: str) -> float:
    """Evaluates the arithmetic expression using a recursive descent parsing technique."""
    evaluator = Evaluator(expr)
    evaluator.skip_whitespace()
    result = evaluator.expr_eval()
